def tokenize_punctuation_keep_alpha(s):
    """Split string into alphanumeric words (case preserved) and non-alphanumeric characters as separate tokens. Whitespace ignored. Empty string returns empty list. Ties impossible. Example: tokenize_punctuation_keep_alpha('a!b') -> ['a', '!', 'b']."""
    tokens = []
    current = ''
    for ch in s:
        if ch.isalnum():
            current += ch
        else:
            if current:
                tokens.append(current)
                current = ''
            if not ch.isspace():
                tokens.append(ch)
    if current:
        tokens.append(current)
    return tokens

